{"file_path": "data/eval/workspace/E24_timeout.py", "content": "import subprocess
import sys

def run_with_timeout(command, timeout=2):
    """Run a command with a timeout. Prints 'TIMEOUT' if it exceeds."""
    try:
        proc = subprocess.run(
            command,
            timeout=timeout,
            capture_output=True,
            text=True,
            shell=True,
        )
        print(proc.stdout, end="")
        print(proc.stderr, end="", file=sys.stderr)
        return proc.returncode
    except subprocess.TimeoutExpired:
        print("TIMEOUT")
        return -1

if __name__ == "__main__":
    if len(sys.argv) > 1:
        cmd = " ".join(sys.argv[1:])
    else:
        cmd = sys.stdin.read().strip()
    sys.exit(run_with_timeout(cmd))
